 perform set_config('request.jwt.claim.sub',owner_id::text,true);perform set_config('request.jwt.claims','{}',true);
 result:=public.moderation_status('product',product);
 if result->'case'->>'correction'<>'Add the missing product detail.' or exists(select 1 from jsonb_array_elements(result->'events') e where e->>'note' is not null or e->>'reviewer' is not null) then raise exception 'Seller audit disclosure/correction failure.';end if;
 reset role;
