 foreach code in array array['content','images','legal'] loop set local role service_role;perform public.moderation_attest(c.id,c.revision,c.policy_id,code,'passed','synthetic_only',now()+interval '1 hour',gen_random_uuid());reset role;end loop;
 select * into c from vetit_moderation.cases where id=c.id;
 perform set_config('request.jwt.claim.sub',admin_id::text,true);perform set_config('request.jwt.claims','{"app_metadata":{"vetit_admin":true}}',true);set local role authenticated;
 result:=public.moderation_decide(c.id,c.version,'screen',gen_random_uuid());v:=(result->>'version')::bigint;req:=gen_random_uuid();
 result:=public.moderation_decide(c.id,v,'approve',req,'{}','Verified synthetic evidence');
 if result is distinct from public.moderation_decide(c.id,v,'approve',req,'{}','Verified synthetic evidence') then raise exception 'Duplicate decision not idempotent.';end if;
 begin perform public.moderation_decide(c.id,v,'approve',req,'{}','Different payload');raise exception 'Changed idempotency payload accepted.';exception when invalid_parameter_value then null;end;
