 if not exists(select 1 from public.listings where id=product and moderation_status='published') then raise exception 'Audited publication failed.';end if;
 reset role;
 if (select count(*) from vetit_moderation.events where request_id=req)<>1 then raise exception 'Duplicate audit action.';end if;
 begin update vetit_moderation.events set note='tamper' where request_id=req;raise exception 'Audit mutated.';exception when insufficient_privilege then null;end;
